let numCurves = 6;
let baseHue = 180;

function setup() {
  createCanvas(1280, 720);
  colorMode(HSB, 360, 100, 100, 1.0);
  background(0);
}

function draw() {
  // 建立極低透明度背景以實現長尾餘暉 (Residual Effect)
  background(0, 0, 0, 0.06);

  let beatVal = window.beatEnergy || 0.0;
  let lowVal = window.audioLow || 0.0;
  let midVal = window.audioMid || 0.0;
  let highVal = window.audioHigh || 0.0;

  if (window.currentChordColor) {
    let chordC = color(window.currentChordColor);
    baseHue = hue(chordC);
  }

  // 變種特有：高頻電流噪波因子
  let glitchActive = (highVal > 0.65 && random(1.0) > 0.45);

  noFill();

  for (let k = 0; k < numCurves; k++) {
    push();
    let curveHue = (baseHue + k * 20 + sin(frameCount * 0.01) * 30) % 360;

    // 霓虹發光感疊加繪製 (多重線條繪製，模擬 glow)
    let strokeW = 1.0 + midVal * 3.5;

    // 1. 繪製外發光
    stroke(curveHue, 95, 100, 0.06 + beatVal * 0.08);
    strokeWeight(strokeW * 4.5);
    drawSingleBezierCurve(k, lowVal, midVal, glitchActive);

    // 2. 繪製核心亮線
    stroke(curveHue, 80, 100, 0.45 + beatVal * 0.35);
    strokeWeight(strokeW * 1.2);
    drawSingleBezierCurve(k, lowVal, midVal, glitchActive);

    pop();
  }
}

function drawSingleBezierCurve(index, lowVal, midVal, glitchActive) {
  var beatVal = window.beatEnergy || 0.0;
  let hOffset = height / (numCurves + 1) * (index + 1);

  // 4個控制點的動態偏移
  let x1 = 80;
  let y1 = hOffset + sin(frameCount * 0.015 + index) * 45;

  // 控制點 1 (受低音頻率擾動)
  let cx1 = width * 0.33;
  let cy1 = hOffset - 180 * lowVal - cos(frameCount * 0.02 + index * 0.5) * 80;

  // 控制點 2 (受中音頻率擾動)
  let cx2 = width * 0.66;
  let cy2 = hOffset + 180 * midVal + sin(frameCount * 0.02 + index * 0.7) * 80;

  let x2 = width - 80;
  let y2 = hOffset + cos(frameCount * 0.015 + index) * 45;

  // 變種特有：鼓點瞬時收縮
  if (beatVal > 0.5) {
    let retract = map(beatVal, 0.5, 1.0, 0.0, 120);
    x1 += retract;
    x2 -= retract;
  }

  // 變種特有：高頻電流 Glitch 斷裂噪波
  if (glitchActive && random(1.0) > 0.5) {
    cy1 += random(-150, 150);
    cy2 += random(-150, 150);
  }

  // 繪製貝氏曲線
  bezier(x1, y1, cx1, cy1, cx2, cy2, x2, y2);
}
